import React, { useState } from 'react';
import { RadioButton, RadioButtonGroup, FormLabel } from 'carbon-components-react';

function RadioGroupExample() {
  const [selectedValue, setSelectedValue] = useState('');
  const [error, setError] = useState('');

  const handleChange = (value) => {
    setSelectedValue(value);
    if (value === 'invalid') {
      setError('Error message goes here');
    } else if (value === 'warn') {
      setError('Warning message goes here');
    } else {
      setError('');
    }
  };

  return (
    <div>
      <FormLabel>Radio button group</FormLabel>
      <RadioButtonGroup
        legendText="Radio button group"
        name="radio-button-group"
        valueSelected={selectedValue}
        onChange={handleChange}
      >
        <RadioButton value="default" labelText="Radio button label" />
        <RadioButton value="invalid" labelText="Radio button label" />
        <RadioButton value="warn" labelText="Radio button label" />
      </RadioButtonGroup>
      {error && <div className="bx--form-requirement">{error}</div>}
    </div>
  );
}

export default RadioGroupExample;
